(function(){
'use strict';
var KEY='welog-section-layout-v2',controls=document.getElementById('controls'),sheet=document.getElementById('sheet');if(!controls||!sheet)return;
var defs={pair:{label:'페어명',scale:100,x:0,y:0},characters:{label:'A+B 캐릭터 세트',scale:100,x:0,y:0},center:{label:'중앙 그림',scale:100,x:0,y:0,crop:{top:0,right:0,bottom:0,left:0}},ok:{label:'OK 표시',scale:100,x:0,y:0},credit:{label:'커미션 출처',scale:100,x:0,y:0}};
var editing=false,selected='',drag=null,cropMode=false,overlay,hud;
function clone(v){return JSON.parse(JSON.stringify(v))}function crop(c){c=c||{};return{top:+c.top||0,right:+c.right||0,bottom:+c.bottom||0,left:+c.left||0}}
function read(){var s={};try{s=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){}var o=clone(defs);Object.keys(o).forEach(function(k){if(!s[k])return;o[k].scale=Math.max(55,Math.min(170,+s[k].scale||100));o[k].x=Math.max(-420,Math.min(420,+s[k].x||0));o[k].y=Math.max(-420,Math.min(420,+s[k].y||0));if(k==='center')o[k].crop=crop(s[k].crop)});return o}function write(s){try{localStorage.setItem(KEY,JSON.stringify(s))}catch(e){}}
function zones(root){var block=root.querySelector('.sheet-commission-footer .commission-block');if(block){var ok=block.querySelector('.welog-ok-zone');if(!ok){var d=Array.from(block.children).find(function(x){return x.tagName==='DIV'&&!x.classList.contains('welog-credit-zone')});if(d)d.classList.add('welog-ok-zone')}var cr=block.querySelector('.welog-credit-zone');if(!cr){cr=document.createElement('div');cr.className='welog-credit-zone';var sm=Array.from(block.children).find(function(x){return x.tagName==='SMALL'}),b=Array.from(block.children).find(function(x){return x.tagName==='B'});if(sm)cr.appendChild(sm);if(b)cr.appendChild(b);block.appendChild(cr)}}return{pair:[root.querySelector('.pair-title-display')].filter(Boolean),characters:[root.querySelector('.profile.left'),root.querySelector('.profile.right')].filter(Boolean),center:[root.querySelector('.center')].filter(Boolean),ok:[root.querySelector('.welog-ok-zone')].filter(Boolean),credit:[root.querySelector('.welog-credit-zone')].filter(Boolean)}}
function apply(root){var s=read(),m=zones(root);Object.keys(m).forEach(function(k){var d=s[k],tr='translate('+d.x+'px,'+d.y+'px) scale('+(d.scale/100)+')';m[k].forEach(function(el){el.dataset.welogLayoutPart=k;el.style.setProperty('transform',tr,'important');el.style.setProperty('transform-origin','center center','important');if(k==='center'){var c=crop(d.crop);el.style.setProperty('clip-path','inset('+c.top+'% '+c.right+'% '+c.bottom+'% '+c.left+'%)','important')}})})}
function rect(k){var a=zones(sheet)[k]||[],rs=a.map(function(x){return x.getBoundingClientRect()}).filter(function(r){return r.width&&r.height});if(!rs.length)return null;var r={left:Math.min.apply(null,rs.map(function(x){return x.left})),top:Math.min.apply(null,rs.map(function(x){return x.top})),right:Math.max.apply(null,rs.map(function(x){return x.right})),bottom:Math.max.apply(null,rs.map(function(x){return x.bottom}))};if(k==='center'){var c=crop(read().center.crop),w=r.right-r.left,h=r.bottom-r.top;r={left:r.left+w*c.left/100,top:r.top+h*c.top/100,right:r.right-w*c.right/100,bottom:r.bottom-h*c.bottom/100}}return r}
function makeOverlay(){if(overlay)return;overlay=document.createElement('div');overlay.className='welog-layout-overlay-fixed';overlay.innerHTML='<div class="welog-layout-box-fixed"><span></span><i class="welog-layout-resize-fixed"></i></div>';document.body.appendChild(overlay);overlay.style.display='none';overlay.querySelector('.welog-layout-resize-fixed').addEventListener('pointerdown',function(e){if(!selected)return;e.preventDefault();e.stopPropagation();var st=read()[selected],r=rect(selected);drag={type:'scale',key:selected,x:e.clientX,start:st.scale,w:Math.max(20,r.right-r.left)};window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true)})}
function draw(){if(!editing||!selected){if(overlay)overlay.style.display='none';return}makeOverlay();var r=rect(selected);if(!r)return;var b=overlay.querySelector('.welog-layout-box-fixed');overlay.style.display='block';b.style.left=r.left+'px';b.style.top=r.top+'px';b.style.width=(r.right-r.left)+'px';b.style.height=(r.bottom-r.top)+'px';b.querySelector('span').textContent=defs[selected].label+' · '+read()[selected].scale+'%'}
function select(k){selected=k;draw()}
function move(e){if(!drag)return;e.preventDefault();var s=read(),d=s[drag.key];if(drag.type==='move'){d.x=Math.max(-420,Math.min(420,Math.round(drag.ox+(e.clientX-drag.x))));d.y=Math.max(-420,Math.min(420,Math.round(drag.oy+(e.clientY-drag.y))))}else{d.scale=Math.max(55,Math.min(170,Math.round(drag.start*((drag.w+(e.clientX-drag.x))/drag.w))))}write(s);apply(sheet);draw()}
function up(){drag=null;window.removeEventListener('pointermove',move,true);window.removeEventListener('pointerup',up,true);window.dispatchEvent(new Event('resize'));draw()}
function centerAll(){var m=zones(sheet),rs=[];Object.keys(m).forEach(function(k){var r=rect(k);if(r)rs.push(r)});if(!rs.length)return;var l=Math.min.apply(null,rs.map(function(r){return r.left})),t=Math.min.apply(null,rs.map(function(r){return r.top})),rr=Math.max.apply(null,rs.map(function(r){return r.right})),bb=Math.max.apply(null,rs.map(function(r){return r.bottom})),sr=sheet.getBoundingClientRect(),dx=((sr.left+sr.right)-(l+rr))/2,dy=((sr.top+sr.bottom)-(t+bb))/2,s=read();Object.keys(defs).forEach(function(k){s[k].x=Math.max(-420,Math.min(420,Math.round(s[k].x+dx)));s[k].y=Math.max(-420,Math.min(420,Math.round(s[k].y+dy)))});write(s);apply(sheet);draw();window.dispatchEvent(new Event('resize'))}
function reset(){write(clone(defs));apply(sheet);draw();window.dispatchEvent(new Event('resize'))}
function makeHud(){if(hud)return;hud=document.createElement('div');hud.className='welog-layout-hud';hud.hidden=true;hud.innerHTML='<div><b>레이아웃 편집</b><span>파트를 직접 드래그해 이동 · 우측 아래 핸들로 크기 조절</span></div><div class="welog-layout-hud-actions"><button type="button" data-center>전체 중앙 정렬</button><button type="button" data-reset>기본 정렬</button><button type="button" data-done>완료</button></div>';document.body.appendChild(hud);hud.querySelector('[data-center]').onclick=centerAll;hud.querySelector('[data-reset]').onclick=reset;hud.querySelector('[data-done]').onclick=exit}
function tool(){var a=controls.querySelector('.layout-ratio-controls');if(!a)return;var box=controls.querySelector('.welog-direct-layout-control');if(!box){box=document.createElement('section');box.className='welog-direct-layout-control';box.innerHTML='<div class="welog-direct-head"><div><b>편집 툴</b><span>시트에서 파트를 직접 선택해 조정합니다.</span></div><button type="button" data-layout-open>편집 툴 열기</button></div><p>페어명 · A+B 세트 · 중앙 그림 · OK 표시 · 커미션 출처를 직접 이동하고 크기를 조절할 수 있습니다.</p>';a.insertAdjacentElement('afterend',box)}box.querySelector('[data-layout-open]').textContent=editing?'편집 툴 닫기':'편집 툴 열기'}
function enter(){editing=true;document.body.classList.add('welog-layout-editing');makeHud();hud.hidden=false;apply(sheet);tool();select('characters')}
function exit(){editing=false;document.body.classList.remove('welog-layout-editing');selected='';if(hud)hud.hidden=true;if(overlay)overlay.style.display='none';tool();window.dispatchEvent(new Event('resize'))}
controls.addEventListener('click',function(e){var b=e.target.closest('[data-layout-open]');if(!b)return;e.preventDefault();e.stopPropagation();editing?exit():enter()},true);
sheet.addEventListener('pointerdown',function(e){if(!editing)return;var hit=e.target.closest&&e.target.closest('[data-welog-layout-part]');if(!hit)return;var k=hit.dataset.welogLayoutPart;if(!k)return;e.preventDefault();e.stopPropagation();select(k);var st=read()[k];drag={type:'move',key:k,x:e.clientX,y:e.clientY,ox:st.x,oy:st.y};window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true)},true);
window.addEventListener('resize',function(){if(editing)draw()});document.addEventListener('input',function(){setTimeout(function(){apply(sheet);if(editing)draw()},0)},true);document.addEventListener('change',function(){setTimeout(function(){apply(sheet);if(editing)draw()},0)},true);
var css=document.createElement('style');css.textContent='.welog-layout-overlay-fixed{position:fixed;inset:0;z-index:2100;pointer-events:none}.welog-layout-box-fixed{position:fixed;box-sizing:border-box;border:1.5px solid #73695f;pointer-events:none}.welog-layout-box-fixed>span{position:absolute;left:-1px;top:-23px;background:#37322e;color:#fff;border-radius:6px 6px 6px 0;padding:4px 7px;font-size:9px;white-space:nowrap}.welog-layout-resize-fixed{position:absolute;right:-7px;bottom:-7px;width:14px;height:14px;border:2px solid #fff;border-radius:50%;background:#37322e;box-shadow:0 1px 6px rgba(0,0,0,.2);pointer-events:auto;cursor:nwse-resize}';document.head.appendChild(css);
tool();apply(sheet);
})();